WITH valid_customers AS (SELECT *, IF(is_active, 'Yes', 'No') AS is_active_label FROM customers WHERE email LIKE '%@startup.io'), signup_year_summary AS (SELECT YEAR(signup_date) AS signup_year, SUM(credit_limit) AS total_credit_limit, MAX(credit_limit) AS max_credit_limit FROM valid_customers GROUP BY YEAR(signup_date)) SELECT signup_year, total_credit_limit, max_credit_limit FROM signup_year_summary ORDER BY max_credit_limit ASC, signup_year ASC LIMIT 20;
